sys_script_client.script:
/**
 * PCE Configuration -- onChange of auto_synchronization.
 *
 * Enables `new_workloads_to_create_at_a_time` only while auto synchronization is on.
 *
 * NO isLoading GUARD, BY DECISION. This script's whole job is to put a field into the state the
 * saved record implies, and form load is exactly when that has to happen. Returning on isLoading
 * would leave an existing record with auto synchronization off rendering the dependent field as
 * editable -- wrong on every open, not just occasionally.
 *
 * The usual advice ("return early on isLoading") is scoped, in ServiceNow's own wording, to
 * scripts *not required to run when the form is loading*. This one is required to.
 */
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (newValue + "" == 'true') {
        g_form.setDisabled('new_workloads_to_create_at_a_time', false);
    } else {
        g_form.setDisabled('new_workloads_to_create_at_a_time', true);
    }
}
